faceBox_pattern.template:
Item {
    id: faceBox
    width: root.maxSize
    height: root.maxSize
    anchors.centerIn: parent
}

knockout_shader_template.frag_source:
#version 440

layout(location = 0) in vec2 qt_TexCoord0;
layout(location = 0) out vec4 fragColor;

layout(std140, binding = 0) uniform buf {
    mat4 qt_Matrix;
    float qt_Opacity;
};

layout(binding = 1) uniform sampler2D source;
layout(binding = 2) uniform sampler2D maskSource;

void main(void) {
    fragColor = texture(source, qt_TexCoord0) * (1.0 - texture(maskSource, qt_TexCoord0).a) * qt_Opacity;
}

knockout_shader_template.qml_usage:
layer.effect: ShaderEffect {
    property variant source: layer2mask
    fragmentShader: "../watchfaces-img/filename.qsb"
}

knockout_shader_template.architecture:
Rectangle { id: layer2mask; anchors.fill: parent; color: Qt.rgba(0,0,0,1); opacity: 0; layer.enabled: true }
Rectangle { id: _mask; anchors.fill: layer2mask; layer.enabled: true; layer.samplerName: "maskSource"
    // mask content (Text items) here
    layer.effect: ShaderEffect { property variant source: layer2mask; fragmentShader: "../watchfaces-img/filename.qsb" }
}

compositor.connections_pattern:
Connections {
    function onDisplayAmbientEntered() { /* deactivate sensors */ }
    function onDisplayAmbientLeft() { /* reactivate */ }
    target: compositor
}

smooth_second_hand.timer:
Timer {
    interval: 16
    repeat: true
    running: !displayAmbient && visible
    onTriggered: {
        var now = new Date();
        secondRot.angle = (now.getSeconds() * 1000 + now.getMilliseconds()) * 6 / 1000;
    }
}

battery_bar.template:
MceBatteryLevel { id: batteryChargePercentage }
Rectangle {
    width: parent.width * batteryChargePercentage.percent / 100
    height: root.maxSize * 0.02
    color: batteryChargePercentage.percent < 30 ? "red" : "green"
}

weather.temperature_function:
function kelvinToTemperatureString(kelvin) {
    var celsius = (kelvin - 273);
    if (!useFahrenheit.value)
        return celsius + "°";
    else
        return Math.round(((celsius) * 9 / 5) + 32) + "°";
}

hrm.sensor:
HrmSensor {
    active: !displayAmbient && hrmSensorActive
    onReadingChanged: {
        root.hrmBpm = reading.bpm;
        root.hrmBpmTime = wallClock.time;
    }
}

step_counter.sensor:
StepCounterSensor {
    id: stepCounter
    active: !displayAmbient
    onReadingChanged: root.stepCount = reading.stepCount
}
